                        'missed': sorted(m for m, r in missed.items() if r['class'] == k)} for k in STIMULUS_CLASSES}
        H.record(request, record_property, 'd08_planted_defects', {
            'scenario': 'D08', 'family': family, 'case': case, 'run_comparison': comparison,
